/**
 * How Six fans (`mutsu-ogi`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/mutsu-ogi";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Six fans radiate from an open eye. Three grouped sets of ribs run to the round edge and three end at the short inner shoulders.","ja":"丸く抜いた要から扇を六つ開きます。三組の骨は丸い縁まで伸ばし、残りの三組は内側の短い弧で止めます。"};

export default construction;
export { construction, description };
